const recalculateInvoicePayment = `-- name: RecalculateInvoicePayment :one
UPDATE invoices i
SET amount_paid = sub.paid,
    status = CASE
        WHEN sub.paid >= i.total THEN 'PAID'
        WHEN sub.paid > 0        THEN 'PARTIAL'
        ELSE i.status
    END,
    updated_at = now()
FROM (
    SELECT COALESCE(SUM(amount), 0)::numeric AS paid
    FROM payments WHERE invoice_id = $1
) sub
WHERE i.id = $1
RETURNING i.id, i.reference, i.sales_order_id, i.kind, i.status, i.issue_date, i.due_date, i.subtotal, i.tax_total, i.total, i.amount_paid, i.created_at, i.updated_at
`

// Recomputes paid amount and status from the payments actually recorded, so
// the invoice can never drift from its ledger. A short payment lands on
// PARTIAL, not PAID.
func (q *Queries) RecalculateInvoicePayment(ctx context.Context, id int64) (Invoice, error) {
	row := q.db.QueryRow(ctx, recalculateInvoicePayment, id)
	var i Invoice
	err := row.Scan(
		&i.ID,
		&i.Reference,
		&i.SalesOrderID,
		&i.Kind,
		&i.Status,
		&i.IssueDate,
		&i.DueDate,
		&i.Subtotal,
		&i.TaxTotal,
		&i.Total,
		&i.AmountPaid,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

